29	// collectPages follows the cursor chain to the end and returns every page.
30	func collectPages(t *testing.T, index *Index, query TxQuery) []TxPage {
31		t.Helper()
32		var pages []TxPage
33		for {
34			page, err := index.QueryTxs(query)
35			if err != nil {
36				t.Fatalf("query failed: %v", err)
37			}
38			pages = append(pages, page)
39			if page.NextCursor == "" {
40				return pages
41			}
42			query.Cursor = page.NextCursor
43		}
44	}
