45	func queryRetainedBlocks() []Block {
46		return []Block{
47			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"x", "x"}},
48			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"y"}},
49		}
50	}
51	
52	func queryOldSuffixBlocks() []Block {
53		return []Block{
54			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a", "c"}},
55			{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"d", "d"}},
56			{Height: 5, Hash: "h5", Parent: "h4", Txs: []string{"e", "f", "g"}},
57		}
58	}
