67	func queryOldChainBlocks() []Block {
68		chain := append([]Block{}, queryRetainedBlocks()...)
69		return append(chain, queryOldSuffixBlocks()...)
70	}
71	
72	func queryNewChainBlocks() []Block {
73		chain := append([]Block{}, queryRetainedBlocks()...)
74		return append(chain, queryNewShortBranch()...)
